import{_ as a,o as t,c as i,ag as r}from"./chunks/framework.8tqBsFWt.js";const u=JSON.parse('{"title":"Licensing Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/licensing-strategy.md","filePath":"decisions/licensing-strategy.md"}'),n={name:"decisions/licensing-strategy.md"};function o(s,e,c,l,d,h){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="licensing-strategy" tabindex="-1">Licensing Strategy <a class="header-anchor" href="#licensing-strategy" aria-label="Permalink to &quot;Licensing Strategy&quot;">​</a></h1><p><strong>Issue:</strong> <a href="https://github.com/talktalkmake/VERA/issues/551" target="_blank" rel="noreferrer">#551</a> · <strong>Date:</strong> 2026-05-03 · <strong>Status:</strong> Canonical</p><hr><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>VERA is <strong>proprietary, closed-source software</strong>. All rights are reserved by talktalkmake. The full licence text is in <code>LICENSE</code> at the repo root.</p><hr><h2 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to &quot;Rationale&quot;">​</a></h2><h3 id="why-proprietary" tabindex="-1">Why proprietary? <a class="header-anchor" href="#why-proprietary" aria-label="Permalink to &quot;Why proprietary?&quot;">​</a></h3><p>VERA is a single-author commercial product. There is no contributor community, no reason to share the implementation, and no strategic benefit to open-sourcing the code at this stage. Proprietary licensing:</p><ul><li>Prevents any other party from forking, repackaging, or reselling VERA</li><li>Removes GPL copyleft contamination as a concern for the codebase itself (we are not distributing a binary that links GPL code to end users)</li><li>Preserves future optionality: open-sourcing later is straightforward; un-open-sourcing after the fact is impossible</li></ul><h3 id="why-not-mit-or-apache-2-0" tabindex="-1">Why not MIT or Apache 2.0? <a class="header-anchor" href="#why-not-mit-or-apache-2-0" aria-label="Permalink to &quot;Why not MIT or Apache 2.0?&quot;">​</a></h3><p>Both MIT and Apache 2.0 would allow any party to take the source code and deploy a competing product. That is the primary risk the proprietary licence is designed to prevent.</p><h3 id="why-not-agpl" tabindex="-1">Why not AGPL? <a class="header-anchor" href="#why-not-agpl" aria-label="Permalink to &quot;Why not AGPL?&quot;">​</a></h3><p>AGPL would require that any modified version of VERA deployed over a network be published under the same terms. This would not prevent a competing SaaS deployment of VERA&#39;s own code if the competitor also published their changes — an unacceptable exposure for a commercial product.</p><hr><h2 id="ai-assisted-development-and-copyright" tabindex="-1">AI-Assisted Development and Copyright <a class="header-anchor" href="#ai-assisted-development-and-copyright" aria-label="Permalink to &quot;AI-Assisted Development and Copyright&quot;">​</a></h2><p>Portions of VERA were written with AI assistance (Claude Code, Anthropic). Under current case law (Thaler v. Perlmutter and subsequent rulings), copyright protection attaches only to work reflecting meaningful human creative choices. Directing <em>how</em> the work is constructed — not merely specifying an objective — establishes authorship.</p><p>The record of human creative direction is maintained in:</p><ul><li><code>docs/decisions/authorship-evidence.md</code> — architectural choices and rejected alternatives</li><li>Commit history — decision rationale in commit messages</li><li>This file — licensing choices and their reasons</li></ul><h3 id="anthropic-plan-tier" tabindex="-1">Anthropic plan tier <a class="header-anchor" href="#anthropic-plan-tier" aria-label="Permalink to &quot;Anthropic plan tier&quot;">​</a></h3><p>VERA operates on the Anthropic Consumer (Pro) plan. Under Anthropic&#39;s Terms of Service, outputs generated via the API are assigned to the account holder. The Pro tier provides narrower copyright-infringement indemnification than the Commercial API or Enterprise tiers; upgrading should be evaluated as VERA scales. Neither tier indemnifies against GPL contamination from training data — this risk is tracked in <code>NOTICE</code>.</p><hr><h2 id="contributor-licence-agreement" tabindex="-1">Contributor Licence Agreement <a class="header-anchor" href="#contributor-licence-agreement" aria-label="Permalink to &quot;Contributor Licence Agreement&quot;">​</a></h2><p>Not required. VERA is single-author. If external contributors are ever added, a CLA must be in place before the first external contribution is merged, to ensure talktalkmake holds all rights and can relicence without restriction.</p><hr><h2 id="dependency-licence-policy" tabindex="-1">Dependency Licence Policy <a class="header-anchor" href="#dependency-licence-policy" aria-label="Permalink to &quot;Dependency Licence Policy&quot;">​</a></h2><p>All dependencies must use permissive open-source licences (MIT, Apache-2.0, ISC, BSD-2-Clause, or equivalent). No GPL, AGPL, LGPL, EUPL, or CDDL dependency may be added to <code>package.json</code> without an explicit decision record here. The dependency audit in <code>NOTICE</code> must be updated when dependencies change.</p><p>Automated licence scanning (FOSSA, Snyk Open Source, or equivalent) should be integrated into CI. See issue #551.</p><hr><h2 id="trademark" tabindex="-1">Trademark <a class="header-anchor" href="#trademark" aria-label="Permalink to &quot;Trademark&quot;">​</a></h2><p>&quot;VERA&quot; and &quot;getvera.site&quot; are not formally registered trademarks as of 2026-05-03. Formal registration should be evaluated once the product reaches commercial scale. Until then, the copyright notice in <code>LICENSE</code> and the <code>NOTICE</code> file are the primary IP protections.</p><hr><h2 id="review-cadence" tabindex="-1">Review Cadence <a class="header-anchor" href="#review-cadence" aria-label="Permalink to &quot;Review Cadence&quot;">​</a></h2><p>This document should be reviewed:</p><ul><li>Before any new funding or acquisition conversation</li><li>Before adding the first external contributor</li><li>When the Anthropic plan tier changes</li><li>When any new dependency is added with an unusual licence</li></ul>',35)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
